export function initMenu(){const e=document.querySelector(".menu-toggle"),t=document.querySelector(".main-nav"),i=document.querySelector(".dropdown");if(e&&t){if(e.addEventListener("click",()=>{const i=t.classList.toggle("is-open");e.setAttribute("aria-expanded",String(i)),e.setAttribute("aria-label",i?"Fechar menu":"Abrir menu")}),i){const e=i.querySelector(":scope > a");e&&e.addEventListener("click",e=>{window.matchMedia("(max-width: 768px)").matches&&(e.preventDefault(),i.classList.toggle("is-mobile-open"))})}t.addEventListener("click",n=>{const r=n.target.closest("a");r&&r!==i?.querySelector(":scope > a")&&(t.classList.remove("is-open"),i?.classList.remove("is-mobile-open"),e.setAttribute("aria-expanded","false"),e.setAttribute("aria-label","Abrir menu"))})}}